import Anthropic from "@anthropic-ai/sdk";

// Транзиентные ошибки API (соединение, 408, 409, 429, 5xx) SDK ретраит сам.
const client = new Anthropic({ maxRetries: 3, timeout: 60_000 });
const MODEL = "claude-opus-5-5"; // актуальные ID моделей смотри в документации
const MAX_STEPS = 12;
const MAX_USD = 0.25;
const PRICE_IN = 2 / 1e6, PRICE_OUT = 10 / 1e6; // иллюстративные цены, $ за токен

const tools: Anthropic.Tool[] = [{
  name: "fetch_url",
  description: "Downloads a web page by URL and returns its text. Use only for a URL you already have; it cannot search.",
  input_schema: { type: "object", properties: { url: { type: "string" } }, required: ["url"] },
}];

const run = { steps: 0, usd: 0, stop: "crashed" }; // пессимистичное значение по умолчанию

// Срабатывает при обычном завершении, process.exit() и непойманных ошибках. Только синхронный код.
process.on("exit", (code) => {
  console.log("[run] stop=" + run.stop + " steps=" + run.steps + " cost=$" + run.usd.toFixed(4) + " exit=" + code);
});
// Обработчик отменяет стандартное «умереть по сигналу», поэтому выходим явно.
process.on("SIGINT", () => { run.stop = "SIGINT"; process.exit(130); });
process.on("SIGTERM", () => { run.stop = "SIGTERM"; process.exit(143); });

type ToolOutput = { content: string; is_error?: boolean };

// Сбой инструмента становится данными для модели, а не исключением.
async function runTool(name: string, input: unknown): Promise<ToolOutput> {
  if (name !== "fetch_url") return { content: "Unknown tool: " + name, is_error: true };
  const { url } = input as { url: string };
  try {
    const res = await fetch(url, { signal: AbortSignal.timeout(15_000) });
    if (!res.ok) {
      return { content: "HTTP " + res.status + " for " + url + ". The page is unavailable; try another source.", is_error: true };
    }
    return { content: (await res.text()).slice(0, 20_000) };
  } catch (err) {
    const kind = err instanceof Error ? err.name : "Error"; // например, TimeoutError
    return { content: kind + " while fetching " + url + ". Try another source.", is_error: true };
  }
}

async function agent(question: string): Promise<string | null> {
  const messages: Anthropic.MessageParam[] = [{ role: "user", content: question }];
  while (true) {
    if (run.steps >= MAX_STEPS) { run.stop = "max_steps"; return null; }
    if (run.usd >= MAX_USD) { run.stop = "budget"; return null; }
    run.steps++;

    const res = await client.messages.create({ model: MODEL, max_tokens: 2048, tools, messages });
    run.usd += res.usage.input_tokens * PRICE_IN + res.usage.output_tokens * PRICE_OUT;
    messages.push({ role: "assistant", content: res.content });

    if (res.stop_reason === "end_turn") {
      run.stop = "final_answer";
      return res.content.filter((b) => b.type === "text").map((b) => b.text).join("");
    }
    if (res.stop_reason !== "tool_use") { run.stop = "stop_reason:" + res.stop_reason; return null; }

    const results: Anthropic.ToolResultBlockParam[] = [];
    for (const b of res.content) {
      if (b.type !== "tool_use") continue;
      const r = await runTool(b.name, b.input);
      console.log("  step " + run.steps + ": " + b.name + " -> " + (r.is_error ? "is_error: " + r.content : "ok"));
      results.push({ type: "tool_result", tool_use_id: b.id, ...r });
    }
    messages.push({ role: "user", content: results });
  }
}

console.log(await agent("Summarise https://example.com/old"));

