appendFileSync("run.jsonl", JSON.stringify({ step: 1, usd: 0.0045, stop_reason: "tool_use" }) + "\n");

// Ретраит только то, что бросает. fetch бросает при сбое сети или таймауте, но не на 404.
async function withRetry<T>(fn: () => Promise<T>, attempts = 3): Promise<T> {
  for (let i = 1; ; i++) {
    try {
      return await fn();
    } catch (err) {
      if (i >= attempts) throw err;
      await new Promise((r) => setTimeout(r, 500 * Math.pow(2, i - 1))); // 0.5 s, 1 s, 2 s...
    }
  }
}

const res = await withRetry(() => fetch("https://example.com/", { signal: AbortSignal.timeout(15_000) }));

